select * from insp_task_item
where tenant_id = #{tenantId}
  and task_id = #{taskId}
order by id asc

select * from insp_task_item
where tenant_id = #{tenantId}
  and task_id = #{taskId}
  and checklist_item_id = #{checklistItemId}
limit 1

select count(1) from insp_task_item
where tenant_id = #{tenantId}
  and task_id = #{taskId}
  and result_status is not null

select count(1) from insp_task_item
where tenant_id = #{tenantId}
  and task_id = #{taskId}
  and result_status = 'ABNORMAL'
